use vstd::prelude::*;

verus! {

/// Simple interval type with f32 endpoints.
pub struct Interval {
    pub lo: f32,
    pub hi: f32,
}

/// A Laguerre series object: coefficients plus two interval fields.
pub struct Laguerre {
    pub coefficients: Vec<f32>,
    pub domain: Interval,
    pub window: Interval,
}

/// Construct a Laguerre object from the given coefficients.
///
/// Requirements: none (no restriction on values/length).
/// Guarantees:
/// - coefficients are stored exactly (same length, same order, same f32 values)
/// - domain and window are both set to the unit interval [0.0, 1.0]
fn make_laguerre(coefficients: Vec<f32>) -> (out: Laguerre)
    ensures
        out.domain.lo == 0.0f32,
        out.domain.hi == 1.0f32,
        out.window.lo == 0.0f32,
        out.window.hi == 1.0f32,
        out.coefficients.len() == coefficients.len(),
        forall|i: int|
            0 <= i < coefficients.len() ==> out.coefficients[i] == coefficients[i],
{
    let domain = Interval { lo: 0.0f32, hi: 1.0f32 };
    let window = Interval { lo: 0.0f32, hi: 1.0f32 };

    // Moving the Vec into the object preserves order and f32 bit-patterns.
    Laguerre { coefficients, domain, window }
}

} // verus!

fn main() {}